// condr agent-hook __CONDR_AGENT_MARKER__ — generated by condr, do not edit.
import { spawn } from "node:child_process"

export default function (api) {
  if (process.env.CONDR_ENV !== "1") return
  const exe = __CONDR_EXECUTABLE__
  const agent = __CONDR_AGENT__
  let queue = Promise.resolve()
  let active = false
  const waiting = new Set()
  const report = (ctx, event, source) => {
    const input = JSON.stringify({ session_id: ctx.sessionManager.getSessionId(), source })
    queue = queue.then(() => new Promise((resolve) => {
      const child = spawn(exe, ["agent-hook", agent, event], {
        stdio: ["pipe", "ignore", "ignore"], timeout: 2000,
      })
      child.on("error", resolve)
      child.on("close", resolve)
      child.stdin.on("error", () => {})
      child.stdin.end(input)
    }))
    return queue.then(() => {})
  }
  const on = (native, handler) => api.on(native, (event, ctx) => {
    if (ctx.mode !== "tui") return
    if (event.sessionId && event.sessionId !== ctx.sessionManager.getSessionId()) return
    return handler(event, ctx)
  })
  const update = (ctx) => report(ctx, waiting.size ? "question-asked" : active ? "prompt-submit" : "stop")
  const session = (event, ctx) => {
    waiting.clear()
    active = !ctx.isIdle()
    // Reload can happen during work; only an idle session start means Idle.
    return report(ctx, active ? "prompt-submit" : "session-start", event.reason)
  }
  on("session_start", session)
  on("agent_start", (_, ctx) => { active = true; return update(ctx) })
  if (agent === "pi") {
    on("agent_settled", (_, ctx) => { active = false; return update(ctx) })
    on("ui_prompt_start", (_, ctx) => { waiting.add("ui"); return update(ctx) })
    on("ui_prompt_end", (_, ctx) => {
      waiting.delete("ui")
      active = !ctx.isIdle()
      return update(ctx)
    })
  } else {
    on("session_switch", session)
    on("session_branch", session)
    on("agent_end", (event, ctx) => {
      active = event.willContinue === true
      if (!active) waiting.clear()
      return update(ctx)
    })
    on("tool_approval_requested", (event, ctx) => {
      waiting.add(`approval:${event.toolCallId}`)
      return update(ctx)
    })
    on("tool_approval_resolved", (event, ctx) => {
      waiting.delete(`approval:${event.toolCallId}`)
      return update(ctx)
    })
    on("tool_execution_start", (event, ctx) => {
      if (event.toolName !== "ask") return
      waiting.add(`ask:${event.toolCallId}`)
      return update(ctx)
    })
    on("tool_result", (event, ctx) => {
      if (!waiting.delete(`ask:${event.toolCallId}`)) return
      return update(ctx)
    })
  }
}
